<?php use Sipe\Models\Catalog; use Sipe\Middleware\Security; $canEdit=$table==='estudiantes'||$user['rol']==='ADMINISTRADOR'; $target=url('catalog').'&table='.$table; ?>
<div class="page-heading"><div><span class="eyebrow">DIRECTORIO INSTITUCIONAL</span><h1><?= e($title) ?></h1><p class="muted">Consulta y conserva la información del servicio.</p></div><?php if($canEdit): ?><a class="button" href="#editor">+ Nuevo registro</a><?php endif ?></div>
<section class="card"><form class="filters" method="get"><input type="hidden" name="r" value="catalog"><input type="hidden" name="table" value="<?= e($table) ?>"><label>Buscar por <?= e(reset($def['fields'])) ?><input name="q" value="<?= e($query) ?>" maxlength="150"></label><button>Buscar</button></form>
<div class="table-wrap"><table><thead><tr><th>ID</th><?php foreach($def['fields'] as $field=>$label): if($field==='password')continue; ?><th><?= e($label) ?></th><?php endforeach ?><th>Vigencia</th><th>Acciones</th></tr></thead><tbody>
<?php foreach($rows as $row): ?><tr><td><?= e($row['id']) ?></td><?php foreach($def['fields'] as $field=>$label): if($field==='password')continue; ?><td><?= e(Catalog::options($field)[$row[$field]]??$row[$field]) ?></td><?php endforeach ?><td><span class="badge"><?= $row['activo']?'Activo':'Inactivo' ?></span></td><td class="actions"><?php if($table==='estudiantes'): ?><a href="<?= e(url('student').'&id='.$row['id']) ?>">Hoja</a><?php endif ?><?php if($canEdit): ?><a href="<?= e($target.'&edit='.$row['id']) ?>#editor">Editar</a><form method="post" action="<?= e($target) ?>" data-confirm="¿Cambiar la vigencia de este registro?"><input type="hidden" name="csrf" value="<?= e(Security::token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="link"><?= $row['activo']?'Desactivar':'Activar' ?></button></form><?php endif ?></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="10">No hay registros. Utiliza el formulario para comenzar.</td></tr><?php endif ?></tbody></table></div><div class="pagination"><?php if($page>1): ?><a href="<?= e($target.'&q='.rawurlencode($query).'&page='.($page-1)) ?>">← Anterior</a><?php endif ?><span>Página <?= e($page) ?> · hasta 50 registros</span><?php if(count($rows)===50): ?><a href="<?= e($target.'&q='.rawurlencode($query).'&page='.($page+1)) ?>">Siguiente →</a><?php endif ?></div></section>
<?php if($canEdit): ?><section class="card" id="editor"><h2><?= $edit?'Editar registro #'.e($edit['id']):'Nuevo registro' ?></h2><form method="post" action="<?= e($target) ?>"><input type="hidden" name="csrf" value="<?= e(Security::token()) ?>"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="form-grid">
<?php foreach($def['fields'] as $field=>$label): $options=Catalog::options($field);$value=$edit[$field]??($field==='tipo_persona'?'ESTUDIANTE':''); ?><label><?= e($label) ?><?php if($options!==null): ?><select name="<?= e($field) ?>" <?= $field==='programa_id'?'':'required' ?>><option value="">Seleccionar</option><?php foreach($options as $v=>$text): ?><option value="<?= e($v) ?>" <?= (string)$v===(string)$value?'selected':'' ?>><?= e($text) ?></option><?php endforeach ?></select><?php else: ?><input name="<?= e($field) ?>" type="<?= $field==='password'?'password':($field==='correo'?'email':'text') ?>" value="<?= $field==='password'?'':e($value) ?>" <?= in_array($field,$def['required'],true)?'required':'' ?> <?= $field==='password'?'minlength="15" maxlength="72" autocomplete="new-password"':'maxlength="5000"' ?>><?php endif ?></label><?php endforeach ?></div><p class="help">Los estudiantes requieren programa académico. Egresados y administrativos requieren aprobación manual por préstamo. Los cambios de grupo son exclusivos del administrador. Los registros se desactivan sin borrar su historial.</p><button>Guardar registro</button><?php if($edit): ?> <a href="<?= e($target) ?>">Cancelar edición</a><?php endif ?></form></section><?php endif ?>
